/**
 * LM-E9 (spec docs/design/registry.md ER-1): the registry's entries — petitions, events and annual rules as data. An
 * entry's conditions are a tree over an allow-listed read model (no code runs), its choices are commands the engine
 * already has, bound to a real instance (an estate, an audit, a suit, a steward). Words live in `*.ko.ts`.
 */

export const REGISTRY_KINDS = ["petition", "event", "annual_rule"] as const;
export type RegistryKind = (typeof REGISTRY_KINDS)[number];

/** ER-1: the read model a condition may name (the adapter in engine/registry.ts reads each from the state). */
export const REGISTRY_FIELDS = [
  "calendar.year", "calendar.season", "population", "treasury",
  "estates.heldOffMap", "estates.delegated", "estates.direct",
  "audit.pending", "suit.open", "claim.open",
  "steward.rules.recurring", "attention.overloaded",
  "faction.relation", "market.exists", "lord.heirAdult", "marriage.open",
  "market.duesPermille", "agency.policy", "timber.order", "steward.lordDecided", "steward.rules.amountAtLeast",
  // The bound target's own facts (an audit, a suit).
  "bound.revealedKept", "bound.stewardLoyalty", "bound.stewardConnected", "bound.suitStage", "bound.evidence",
] as const;
export type RegistryField = (typeof REGISTRY_FIELDS)[number];

/** `has`/`lacks`: a list field (the bound suit's evidence) holds / does not hold the value. */
export const REGISTRY_OPS = ["eq", "ne", "gte", "lte", "in", "has", "lacks"] as const;
export type RegistryOp = (typeof REGISTRY_OPS)[number];

export type RegistryCondition =
  | { readonly all: readonly RegistryCondition[] }
  | { readonly any: readonly RegistryCondition[] }
  | { readonly not: RegistryCondition }
  | { readonly field: RegistryField; readonly op: RegistryOp; readonly value: number | string | boolean | readonly (number | string)[]; readonly faction?: string };

/** ER-1: what an occurrence is bound to (its commands take their target from it). */
export const REGISTRY_BINDS = ["none", "delegated_estate", "held_estate", "pending_audit", "open_suit", "open_claim"] as const;
export type RegistryBind = (typeof REGISTRY_BINDS)[number];

/** ER-1: an effect — a command the engine has (the bound target fills its ids), or a ledger line / timed term. */
export type RegistryEffect =
  | { readonly command: "set_project_subsidy"; readonly kind: string; readonly amount: number }
  | { readonly command: "set_market_dues"; readonly permille: number }
  | { readonly command: "set_estate_policy"; readonly policy: "growth" | "revenue" | "stability" | "defence" }
  | { readonly command: "set_audit_mode"; readonly mode: "accounts" | "visit" }
  | { readonly command: "answer_audit"; readonly choice: "punish" | "replace" | "tolerate" }
  | { readonly command: "set_estate_oversight"; readonly mode: "steward" | "direct" }
  | { readonly command: "add_suit_evidence"; readonly evidence: "charter" | "witnesses" | "deed" | "court_roll" | "possession_years" }
  | { readonly command: "file_suit" }
  | { readonly command: "order_timber"; readonly amount: number }
  | { readonly command: "faction_relation"; readonly faction: string; readonly delta: number }
  | { readonly command: "treasury"; readonly amount: number }
  | { readonly command: "term"; readonly term: "remission" | "installments"; readonly what: string; readonly amountPerYear: number; readonly years: number }
  | { readonly command: "rights_scope"; readonly sharePermille: number }
  | { readonly command: "set_exception_rules"; readonly recurring?: boolean; readonly amountAtLeast?: number | null }
  | { readonly command: "enforce_possession" }
  | { readonly command: "none" };

export interface RegistryChoice {
  readonly id: string;
  readonly effects: readonly RegistryEffect[];
  /** A choice's own precondition (the drafts' "this choice only when …"). */
  readonly requires?: RegistryCondition;
}

export interface RegistryEntry {
  readonly id: string;
  readonly kind: RegistryKind;
  /** Where it came from (a content draft's id, FIX-14's home petitions). */
  readonly source: string;
  readonly years: { readonly fromYear: number; readonly toYear: number };
  /** Seasons it may come in (0 spring … 3 winter); absent = any. */
  readonly seasons?: readonly number[];
  readonly conditions?: RegistryCondition;
  readonly frequency: { readonly chancePermille: number; readonly weight: number; readonly minGapSeasons: number; readonly maxPerYear: number };
  /** `once`: one in the whole game; `once_per_target`: one per bound instance; `cooldown`: again after its seasons. */
  readonly recurrence: { readonly mode: "once" | "once_per_target" | "cooldown"; readonly cooldownSeasons: number; readonly maxOccurrences: number };
  readonly exclusiveGroup?: string;
  /** The faction that sends it (the card's sender). */
  readonly sender: string;
  readonly bind: RegistryBind;
  readonly choices: readonly RegistryChoice[];
  /** The choice applied once when an offer lapses unanswered (absent = nothing). */
  readonly lapseChoice?: string;
  /** May a steward answer it by precedent (ER-6)? */
  readonly precedent: boolean;
  /** The picture's id; null = none yet (the Astra request list). */
  readonly artId: string | null;
  /** A generator the engine runs instead of the generic draw (FIX-14's home cycle). */
  readonly generator?: "home_cycle";
}

/**
 * LM-E9 (ER-1): every registry entry as data, with no engine imports — the history ledger and the lord bot read an
 * entry's choices from here (engine/registry.ts validates and loads the same list; a module cycle through the engine
 * would leave constants uninitialised at load).
 */
import { DRAFT_EVENT_ENTRIES } from "./draftEvents";
import { HOME_PETITION_ENTRIES } from "./homePetitions";
import type { RegistryEntry } from "./registryTypes";

export const ALL_REGISTRY_ENTRIES: readonly RegistryEntry[] = [...HOME_PETITION_ENTRIES, ...DRAFT_EVENT_ENTRIES];

const BY_ID: ReadonlyMap<string, RegistryEntry> = new Map(ALL_REGISTRY_ENTRIES.map(entry => [entry.id, entry]));

export function registryEntryData(id: string): RegistryEntry | undefined {
  return BY_ID.get(id);
}

// --- ER-2 load and validation ----------------------------------------------------------------------------------------

export interface RegistryRejection { readonly id: string; readonly reason: string }

const COMMANDS: ReadonlySet<string> = new Set(["set_project_subsidy", "set_market_dues", "set_estate_policy", "set_audit_mode", "answer_audit",
  "set_estate_oversight", "add_suit_evidence", "file_suit", "order_timber", "faction_relation", "treasury", "term", "rights_scope",
  "set_exception_rules", "enforce_possession", "none"]);

function conditionProblem(condition: RegistryCondition): string | null {
  if ("all" in condition) return condition.all.length === 0 ? "empty all" : condition.all.map(conditionProblem).find(problem => problem !== null) ?? null;
  if ("any" in condition) return condition.any.length === 0 ? "empty any" : condition.any.map(conditionProblem).find(problem => problem !== null) ?? null;
  if ("not" in condition) return conditionProblem(condition.not);
  if (!(REGISTRY_FIELDS as readonly string[]).includes(condition.field)) return `unknown field ${condition.field}`;
  if (!(REGISTRY_OPS as readonly string[]).includes(condition.op)) return `unknown op ${condition.op}`;
  if (condition.op === "in" && !Array.isArray(condition.value)) return "in needs a list";
  if ((condition.op === "has" || condition.op === "lacks") && (condition.field !== "bound.evidence" || typeof condition.value !== "string")) return `${condition.op} needs bound.evidence and a kind`;
  if ((condition.op === "gte" || condition.op === "lte") && typeof condition.value !== "number") return `${condition.op} needs a number`;
  if (condition.field === "faction.relation" && condition.faction === undefined) return "faction.relation needs a faction";
  return null;
}

/** ER-2: an entry's problem, or null — a wrong entry is left out whole. */
export function entryProblem(entry: RegistryEntry): string | null {
  if (typeof entry.id !== "string" || entry.id.length === 0) return "no id";
  if (!(REGISTRY_KINDS as readonly string[]).includes(entry.kind)) return `unknown kind ${entry.kind}`;
  if (!(REGISTRY_BINDS as readonly string[]).includes(entry.bind)) return `unknown bind ${entry.bind}`;
  if (entry.years.fromYear > entry.years.toYear) return "empty window";
  const frequency = entry.frequency;
  if (frequency.chancePermille < 0 || frequency.chancePermille > 1000) return "chance outside 0–1000";
  if (frequency.weight < 1 || !Number.isInteger(frequency.weight)) return "weight must be a whole number of 1 or more";
  if (frequency.maxPerYear < 1) return "maxPerYear must be 1 or more";
  if (entry.recurrence.mode === "once" && entry.recurrence.maxOccurrences !== 1) return "once must have maxOccurrences 1";
  if (entry.choices.length < 2) return "fewer than two choices";
  if (new Set(entry.choices.map(choice => choice.id)).size !== entry.choices.length) return "choice ids repeat";
  for (const choice of entry.choices) {
    for (const effect of choice.effects) if (!COMMANDS.has(effect.command)) return `unknown command ${effect.command}`;
    if (choice.requires !== undefined) { const problem = conditionProblem(choice.requires); if (problem !== null) return `${choice.id}: ${problem}`; }
  }
  if (entry.lapseChoice !== undefined && !entry.choices.some(choice => choice.id === entry.lapseChoice)) return "lapse choice not among the choices";
  if (entry.conditions !== undefined) { const problem = conditionProblem(entry.conditions); if (problem !== null) return problem; }

/** The real instances an entry may bind to now (sorted); [""] for an entry bound to nothing. */
export function boundTargets(state: GameState, entry: RegistryEntry): readonly string[] {
  const estates = estatesOf(state);
  switch (entry.bind) {
    case "none": return [""];
    case "held_estate": return heldOffMapEstates(state).map(estate => estate.id).sort();
    case "delegated_estate": return stewardshipOf(state).oversight.filter(entry => entry.mode === "steward").map(entry => entry.estateId).sort();
    case "pending_audit": return pendingAudits(state).map(audit => audit.id).sort();
    case "open_suit": return estates.suits.filter(suit => suit.stage !== "closed" && suit.stage !== "judged").map(suit => suit.id).sort();
    case "open_claim": return estates.claims.filter(claim => claim.status === "open").map(claim => claim.id).sort();
  }
}

// --- ER-4 effects ------------------------------------------------------------------------------------------------------

/** One effect on the state, or null when the engine refuses it (nothing changed). */
function applyEffect(state: GameState, effect: RegistryEffect, boundId: string, occurrenceId: string): GameState | null {
  const changed = (next: GameState) => (next === state ? null : next);
  const audit = pendingAudits(state).find(entry => entry.id === boundId);
  const estateId = audit?.estateId ?? boundId;
  switch (effect.command) {
    case "none": return state;
    case "set_project_subsidy": return changed(setProjectSubsidy(state, effect.kind as BuildingKind, effect.amount));
    case "set_market_dues": return changed(setMarketDues(state, effect.permille));
    case "set_estate_policy": return changed(setEstatePolicy(state, effect.policy));
    case "set_audit_mode": return changed(setAuditMode(state, estateId, effect.mode));
    case "answer_audit": return changed(answerAudit(state, boundId, effect.choice));
    case "set_estate_oversight": return changed(setEstateOversight(state, estateId, effect.mode));
    case "add_suit_evidence": return changed(addSuitEvidence(state, boundId, effect.evidence));
    case "file_suit": return changed(fileSuit(state, boundId));
    case "order_timber": return changed(orderTimber(state, effect.amount));
    case "faction_relation": {
      // The relation moves through the ledger (history.ts reads the answered occurrence); here only check the faction.
      return state.factions?.factions.some(faction => faction.id === effect.faction) === true ? state : null;
    }
    case "treasury": {
      if (effect.amount < 0 && treasuryBalance(state) < -effect.amount) return null;
      const posted = postLedgerEntries(state, [{ account: "cash", category: "registry_settlement", amount: effect.amount, sourceRefs: [{ type: "actor", id: occurrenceId }] }]);
      return { ...state, ledger: posted.ledger, treasuryCoin: posted.treasuryCoin };
    }
    case "term": return startTerm(state, effect, occurrenceId);
    case "rights_scope": return ruleRightsScope(state, boundId, effect.sharePermille);
    case "set_exception_rules": {
      if (state.stewardship === undefined) return null;
      const rules = stewardshipOf(state).rules;
      return changed(setExceptionRules(state, { ...rules, ...(effect.recurring === undefined ? {} : { recurring: effect.recurring }),
        ...(effect.amountAtLeast === undefined ? {} : { amountAtLeast: effect.amountAtLeast }) }));
    }
    case "enforce_possession": return changed(enforcePossession(state, boundId));
  }
}

/** ER-4: a choice's effects in order on a copy — all applied, or none (the state as it was). */
export function applyChoice(state: GameState, entry: RegistryEntry, choiceId: string, boundId: string, occurrenceId: string): GameState | null {
  const choice = entry.choices.find(candidate => candidate.id === choiceId);
  if (choice === undefined || !conditionHolds(state, choice.requires, boundId)) return null;
  let next = state;
  for (const effect of choice.effects) {
    const applied = applyEffect(next, effect, boundId, occurrenceId);
    if (applied === null) return null;
    next = applied;
  }
  return next;
}

/** ER-4: the choices that can be carried out now (each tried on a copy). */
export function enabledChoices(state: GameState, entry: RegistryEntry, boundId: string, occurrenceId: string): readonly string[] {
  return entry.choices.filter(choice => applyChoice(state, entry, choice.id, boundId, occurrenceId) !== null).map(choice => choice.id);
}

function startTerm(state: GameState, effect: Extract<RegistryEffect, { command: "term" }>, source: string): GameState | null {
  if (effect.years < 1 || effect.amountPerYear < 0) return null;
  const registry = registryOf(state);
  // A remission of the market dues: the dues fall to `amountPerYear` (permille, the lord's lowest is 250‰) now; the term
  // restores the dues it found at its end.
  let next = state;
  let restore: number | undefined;
  if (effect.term === "remission" && effect.what === "market_dues") {
    restore = state.agency?.duesPermille;
    next = setMarketDues(state, effect.amountPerYear);
    if (next === state || restore === undefined) return null;
  }
  const term: RegistryTerm = { id: `term-${registry.nextTerm}`, kind: effect.term, what: effect.what, amountPerYear: effect.amountPerYear, years: effect.years,
    startTick: state.tick, endTick: state.tick + effect.years * YEAR, source, settledYears: 0, ...(restore === undefined ? {} : { restore }), status: "running" };
  return { ...next, registry: { ...registryOf(next), terms: [...registryOf(next).terms, term], nextTerm: registry.nextTerm + 1 } };
}

/**
 * ER-7: a year's instalment, paid from the cash; what the cash cannot cover goes to the arrears account and queue, as the
 * war's charges do (paid off at the period close like unpaid upkeep, counted by the failure ladder's arrears).
 */
function payInstalment(state: GameState, term: RegistryTerm): GameState {
  const sources = [{ type: "actor", id: term.source }, { type: "actor", id: term.id }] as const;
  const paid = Math.min(term.amountPerYear, Math.max(0, treasuryBalance(state)));
  const owed = term.amountPerYear - paid;
  const postings: LedgerPosting[] = [];
  if (paid > 0) postings.push({ account: "cash", category: "instalment", amount: -paid, sourceRefs: [...sources] });
  if (owed > 0) postings.push({ account: "arrears", category: "instalment", amount: owed, sourceRefs: [...sources, { type: "claim", id: `instalment:${state.tick}`, detail: "unpaid" }] });
  if (postings.length === 0) return state;
  const posted = postLedgerEntries(state, postings);
  const money = state.money ?? EMPTY_MONEY;
  const arrear: UpkeepArrear = { tick: state.tick, amount: owed, facility: sources[0], category: "instalment" };
  return { ...state, treasuryCoin: posted.treasuryCoin, ledger: posted.ledger, ...(owed > 0 ? { money: { ...money, arrears: [...money.arrears, arrear] } } : {}) };
}

/** ER-7: at each year's turn the running terms settle a year (an instalment paid, a remission taken); at their end they stop. */
function settleTerms(state: GameState): GameState {
  const registry = registryOf(state);
  if (!registry.terms.some(term => term.status === "running")) return state;
  let next = state;
  const terms = registry.terms.map(term => {
    if (term.status !== "running") return term;
    const due = Math.floor((state.tick - term.startTick) / YEAR);
    let settled = term;
    if (due > term.settledYears && term.kind === "installments") next = payInstalment(next, term);
    if (due > term.settledYears) settled = { ...settled, settledYears: due };
    if (state.tick >= term.endTick) {
      if (term.kind === "remission" && term.what === "market_dues" && term.restore !== undefined) next = setMarketDues(next, term.restore);
      settled = { ...settled, status: "ended" };
    }
    return settled;
  });
  return { ...next, registry: { ...registryOf(next), terms } };
}

// --- ER-8 rights scope --------------------------------------------------------------------------------------------------

function ruleRightsScope(state: GameState, suitId: string, sharePermille: number): GameState | null {
  const estates = estatesOf(state);
  const suit = estates.suits.find(entry => entry.id === suitId);
  if (suit === undefined || suit.pieceId === undefined || sharePermille < 0 || sharePermille > 2000) return null;
  let found = false;
  const updated = estates.estates.map(estate => estate.id !== suit.estateId ? estate : { ...estate, pieces: estate.pieces.map(piece => {
    if (piece.id !== suit.pieceId) return piece;
    found = true;
    return { ...piece, scope: { sharePermille, ruledTick: state.tick, suitId } };
  }) });
  return found ? { ...state, estates: { ...estates, estates: updated } } : null;

export function fileSuitRefusal(state: GameState, claimId: string): SuitRefusal | null {
  const estates = estatesOf(state);
  const claim = estates.claims.find(entry => entry.id === claimId);
  if (claim === undefined) return "no_claim";
  if (claim.status !== "open") return "not_open";
  const found = target(estates, claim.estateId, claim.pieceId);
  if (found === null) return "no_claim";
  if (titleOf(found) === claim.claimant) return "own_title";
  if (claim.claimant === LORD && treasuryBalance(state) < (SUIT_STAGE_COST.filed ?? 0)) return "treasury";
  return null;
}

/** ES-7: a claim filed as a suit against the title holder (the filing fee paid). Refused: the state unchanged. */
export function fileSuit(state: GameState, claimId: string): GameState {
  if (fileSuitRefusal(state, claimId) !== null) return state;
  const estates = estatesOf(state);
  const claim = estates.claims.find(entry => entry.id === claimId)!;
  const found = target(estates, claim.estateId, claim.pieceId)!;
  const suit: Suit = { id: `suit-${estates.nextSuit}`, claimId, plaintiff: claim.claimant, defendant: titleOf(found), estateId: claim.estateId,
    ...(claim.pieceId === undefined ? {} : { pieceId: claim.pieceId }), stage: "filed", stageSince: state.tick, patronSupport: 0, enforcements: 0, costs: SUIT_STAGE_COST.filed ?? 0 };
  const paid = pay(state, suit, SUIT_STAGE_COST.filed ?? 0, "filed");
  if (paid === null) return state;
  return { ...paid, estates: { ...estates, suits: [...estates.suits, suit], nextSuit: estates.nextSuit + 1,
    claims: estates.claims.map(entry => entry.id === claimId ? { ...entry, status: "suing" as const } : entry) } };
}

/** ES-7: evidence brought while the suit is filed or gathering it (once per kind; old possession counts its years). */
export function addSuitEvidence(state: GameState, suitId: string, kind: Evidence["kind"]): GameState {
  const estates = estatesOf(state);
  const suit = estates.suits.find(entry => entry.id === suitId);
  if (suit === undefined || (suit.stage !== "filed" && suit.stage !== "evidence")) return state;
  const claim = estates.claims.find(entry => entry.id === suit.claimId)!;
  if (claim.evidence.some(entry => entry.kind === kind)) return state;
  const paid = pay(state, suit, EVIDENCE_COST[kind], `evidence:${kind}`);
  if (paid === null) return state;
  const withEvidence = withClaim(paid, { ...claim, evidence: [...claim.evidence, { kind, weight: EVIDENCE_WEIGHT[kind], tick: state.tick }] });
  return withSuit(withEvidence, { ...suit, costs: suit.costs + EVIDENCE_COST[kind] });
}

/** ES-7: a faction won over as the suit's patron during the patronage stage — its relation with the lord, capped. */
export function seekSuitPatron(state: GameState, suitId: string, factionId: string): GameState {
  const suit = estatesOf(state).suits.find(entry => entry.id === suitId);
  if (suit === undefined || suit.stage !== "patronage" || suit.patron !== undefined) return state;
  const relation = state.factions?.factions.find(faction => faction.id === factionId)?.relation ?? 0;
  if (relation < PATRON_MIN_RELATION) return state;
  return withSuit(state, { ...suit, patron: factionId, patronSupport: Math.min(PATRON_SUPPORT_MAX, relation) });
}

/** ES-7 API: the hearing's two sides now — the claim with its evidence and patron, the defence's title and hold. */
export function suitHearing(state: GameState, suitId: string): { readonly plaintiff: number; readonly defence: number } | null {

/** NG-6: the contract's future terms as promises — the lord's payments and support, the counterpart's word on the will. */
function contractPromises(diplomacy: DiplomacyState, negotiation: Negotiation, terms: readonly Term[], tick: number): DiplomacyState {
  let next = diplomacy;
  const base = { negotiationId: negotiation.id, witnesses: MARRIAGE_WITNESSES, stake: PROMISE_STAKE };
  for (const term of terms) {
    // FIX-12 (item 1, NG-6): a debt taken on by instalments is a promise a year, the last one taking the remainder.
    if (term.giver === "proposer" && term.kind === "debt_assumption") {
      const total = term.amount ?? 0;
      const years = Math.max(1, Math.min(DEBT_INSTALMENT_MAX_YEARS, term.years ?? 1));
      const instalment = Math.ceil(total / years);
      for (let year = 1; year <= years; year += 1) {
        const amount = year < years ? instalment : total - instalment * (years - 1);
        if (amount <= 0) continue;
        next = promise(next, { ...base, promisor: LORD, promisee: negotiation.counterpart, term: term.kind, amount, deadline: tick + year * PROMISE_PAYMENT_TICKS }).diplomacy;
      }
    }
    if (term.giver === "proposer" && term.kind === "pension") {
      for (let year = 1; year <= (term.years ?? 1); year += 1) {
        next = promise(next, { ...base, promisor: LORD, promisee: negotiation.counterpart, term: term.kind, amount: term.amount ?? 0, deadline: tick + year * PROMISE_PAYMENT_TICKS }).diplomacy;
      }
    }
    if (term.giver === "proposer" && term.kind === "political_support") {
      next = promise(next, { ...base, promisor: LORD, promisee: negotiation.counterpart, term: term.kind, deadline: tick + PROMISE_SUPPORT_TICKS }).diplomacy;
    }
    if (term.giver === "counterpart" && term.kind === "inheritance_non_infringement") {
      next = promise(next, { ...base, promisor: negotiation.counterpart, promisee: LORD, term: term.kind, deadline: tick + MARRIAGE_TIMES.fatherDies }).diplomacy;
    }
  }
  return next;
}

/** NG-6 API: the lord keeps a promise before its deadline — a payment is paid from the treasury; support is given. */
export function keepPromise(state: GameState, promiseId: string): GameState {
  const diplomacy = diplomacyOf(state);
  const record = diplomacy.promises.find(entry => entry.id === promiseId);
  if (record === undefined || record.status !== "open" || record.promisor !== LORD || state.tick > record.deadline) return state;
  let next = state;
  const amount = record.amount ?? 0;
  if (amount > 0) {
    if (treasuryBalance(state) < amount) return state;
    const posted = postLedgerEntries(state, [{ account: "cash", category: "promise_payment", amount: -amount,
      sourceRefs: [{ type: "claim", id: record.id, detail: record.term }, { type: "actor", id: record.promisee }] }]);
    next = { ...next, ledger: posted.ledger, treasuryCoin: posted.treasuryCoin };
  }
  return settle(next, record.id, "kept");
}

/** TA-6 ②: `amount` 0 withdraws the subsidy on that kind; one past a quarter of the treasury is refused with its reason. */
export function setProjectSubsidy(state: GameState, kind: BuildingKind, amount: number): GameState {
  const agency = state.agency;
  if (agency === undefined || !Number.isInteger(amount) || amount < 0) return state;
  const others = agency.subsidies.filter(subsidy => subsidy.kind !== kind);
  if (amount === 0) return others.length === agency.subsidies.length ? state : { ...state, agency: { ...agency, subsidies: others } };
  const refusal = subsidyRefusal(state, kind, amount);
  if (refusal !== null) return { ...state, agency: { ...agency, lastRefusal: refusal } };
  const subsidy: ProjectSubsidy = { id: `subsidy-${agency.nextSubsidy}`, kind, amount };
  return { ...state, agency: { ...agency, subsidies: [...others, subsidy], nextSubsidy: agency.nextSubsidy + 1 } };
}

/** TA-6 ③: the stall fee the lord asks, permille of the usual (250‰…2000‰). */
export function setMarketDues(state: GameState, permille: number): GameState {
